const crypto = require('crypto');

const authResult = $('Authenticate to KSeF').first().json;
const certsResponse = $input.first().json;
const clientData = $('Process Each Client').first().json;

// Find SymmetricKeyEncryption certificate
let certBase64 = '';
if (Array.isArray(certsResponse)) {
  const symCert = certsResponse.find(c => {
    const usages = c.usage || [];
    return usages.some(u => (u.usage || []).includes('SymmetricKeyEncryption'));
  }) || certsResponse[0];
  certBase64 = symCert.certificate || symCert.publicKey || '';
} else {
  certBase64 = certsResponse.certificate || certsResponse.publicKey || '';
}

const certPem = '-----BEGIN CERTIFICATE-----\n' + certBase64.match(/.{1,64}/g).join('\n') + '\n-----END CERTIFICATE-----';
const publicKey = crypto.createPublicKey(certPem);

// Generate AES-256 key and IV
const aesKey = crypto.randomBytes(32);
const iv = crypto.randomBytes(16);

// Encrypt AES key with RSA-OAEP SHA-256
const encryptedKey = crypto.publicEncrypt({
  key: publicKey,
  padding: crypto.constants.RSA_PKCS1_OAEP_PADDING,
  oaepHash: 'sha256',
}, aesKey);

return [{
  json: {
    accessToken: authResult.accessToken,
    refreshToken: authResult.refreshToken,
    encryptedSymmetricKey: encryptedKey.toString('base64'),
    initializationVector: Buffer.from(iv).toString('base64'),
    aesKeyHex: aesKey.toString('hex'),
    ivHex: iv.toString('hex'),
    client_nip: clientData.nip,
    hwm_sales: clientData.hwm_sales,
    hwm_purchases: clientData.hwm_purchases
  }
}];

const sessionResp = $input.first().json;
const keyData = $('Generate Session Keys').first().json;

const sessionRef = sessionResp.referenceNumber;
if (!sessionRef) {
  throw new Error('No session reference in response: ' + JSON.stringify(sessionResp));
}

return [{
  json: {
    sessionRef: sessionRef,
    accessToken: keyData.accessToken,
    client_nip: keyData.client_nip,
    hwm_sales: keyData.hwm_sales,
    hwm_purchases: keyData.hwm_purchases,
    aesKeyHex: keyData.aesKeyHex,
    ivHex: keyData.ivHex
  }
}];

const queryData = $('Prepare Invoice Query').first().json;

let salesInvoices = [];
let purchaseInvoices = [];

function extractNip(subject) {
  if (!subject) return '';
  if (typeof subject === 'string') return subject;
  if (subject.nip) return subject.nip;
  if (subject.identifier) {
    if (typeof subject.identifier === 'string') return subject.identifier;
    if (subject.identifier.value) return subject.identifier.value;
  }
  return '';
}

function mapInvoice(inv, direction) {
  return {
    ksefNumber: inv.ksefNumber,
    invoiceNumber: inv.invoiceNumber,
    invoiceType: inv.invoiceType,
    sellerNip: extractNip(inv.seller),
    buyerNip: extractNip(inv.buyer),
    netAmount: inv.netAmount || 0,
    vatAmount: inv.vatAmount || 0,
    grossAmount: inv.grossAmount || 0,
    currency: inv.currency || 'PLN',
    issueDate: inv.issueDate || '',
    invoicingDate: inv.invoicingDate || '',
    acquisitionDate: inv.acquisitionDate || '',
    permanentStorageDate: inv.permanentStorageDate || '',
    direction: direction
  };
}

try {
  const salesResp = $('Query Sales Invoices').first().json;
  salesInvoices = (salesResp.invoices || []).map(inv => mapInvoice(inv, 'sales'));
} catch(e) { /* no sales */ }

try {
  const purchResp = $('Query Purchase Invoices').first().json;
  purchaseInvoices = (purchResp.invoices || []).map(inv => mapInvoice(inv, 'purchase'));
} catch(e) { /* no purchases */ }

const allInvoices = [...salesInvoices, ...purchaseInvoices];

if (allInvoices.length === 0) {
  return [{ json: { hasInvoices: false, count: 0, sessionRef: queryData.sessionRef, accessToken: queryData.accessToken, client_nip: queryData.client_nip } }];
}

return allInvoices.map(inv => ({
  json: {
    ...inv,
    hasInvoices: true,
    sessionRef: queryData.sessionRef,
    accessToken: queryData.accessToken,
    client_nip: queryData.client_nip
  }
}));

const error = $input.first().json;
return [{
  json: {
    error_type: 'invoice_retrieval_error',
    message: error.message || error.execution?.error?.message || 'Unknown error',
    workflow: 'KSeF - Invoice Retrieval v2',
    timestamp: new Date().toISOString()
  }
}];

const err = $json.error?.message || 'Session open failed';
const nip = $('Process Each Client').item.json.nip || '?';
return {json:{error:err,client_nip:nip}};

